<script>
"use strict";
/* WastedToken Mint — orthographic per-pixel ray-cast coin renderer.
   Cylinder solid, bump-mapped faces from procedural height maps,
   analytic reeded edge, metallic env reflection + specular lights. */
var TAU=Math.PI*2, RAD=1.0, TH=0.108;

/* ---------- 1. procedural face height maps -> normal maps ---------- */
function arcText(g,cx,cy,txt,r,size,color,ca,spread,flip,font){
  g.save();g.fillStyle=color;g.font="bold "+size+"px "+(font||'Georgia,"Times New Roman",serif');
  g.textAlign="center";g.textBaseline="middle";
  for(var i=0,n=txt.length;i<n;i++){
    var f=n===1?0.5:i/(n-1), a=ca+(f-0.5)*spread*(flip?-1:1);
    g.save();g.translate(cx+Math.cos(a)*r,cy+Math.sin(a)*r);
    g.rotate(a+(flip?-Math.PI/2:Math.PI/2));g.fillText(txt.charAt(i),0,0);g.restore();
  }
  g.restore();
}
function star(g,x,y,ro,ri){
  g.save();g.translate(x,y);g.beginPath();
  for(var i=0;i<10;i++){var rr=i%2?ri:ro,a=i/10*TAU-Math.PI/2;
    g[i?"lineTo":"moveTo"](Math.cos(a)*rr,Math.sin(a)*rr);}
  g.closePath();g.fill();g.restore();
}
function buildFaceMap(N,side){
  var c=document.createElement("canvas");c.width=c.height=N;
  var g=c.getContext("2d"),cx=N/2,cy=N/2,R=N/2;
  g.fillStyle="#000";g.fillRect(0,0,N,N);
  g.save();g.beginPath();g.arc(cx,cy,R,0,TAU);g.clip();
  g.fillStyle="#4c4c4c";g.fillRect(0,0,N,N);
  /* engine-turned texture */
  g.save();g.globalAlpha=.18;g.strokeStyle="#8f8f8f";g.lineWidth=.004*N;
  for(var q=0;q<44;q++){var a0=q/44*TAU;g.beginPath();
    g.arc(cx+Math.cos(a0)*.20*R,cy+Math.sin(a0)*.20*R,.42*R,0,TAU);g.stroke();}
  g.restore();
  /* common framing */
  g.lineWidth=.030*N;g.strokeStyle="#151515";g.beginPath();g.arc(cx,cy,.988*R,0,TAU);g.stroke();
  g.lineWidth=.052*N;g.strokeStyle="#cbcbcb";g.beginPath();g.arc(cx,cy,.933*R,0,TAU);g.stroke();
  g.lineWidth=.009*N;g.strokeStyle="#e0e0e0";g.beginPath();g.arc(cx,cy,.894*R,0,TAU);g.stroke();
  g.lineWidth=.150*N;g.strokeStyle="#3a3a3a";g.beginPath();g.arc(cx,cy,.800*R,0,TAU);g.stroke();
  g.lineWidth=.013*N;g.strokeStyle="#222";g.beginPath();g.arc(cx,cy,.700*R,0,TAU);g.stroke();
  g.lineWidth=.008*N;g.strokeStyle="#aaa";g.beginPath();g.arc(cx,cy,.686*R,0,TAU);g.stroke();

  if(side==="front"){
    arcText(g,cx,cy,"WASTEDTOKEN  MINT",.800*R,.086*N,"#f4f4f4",-Math.PI/2,2.15,false);
